-- YG-1288–1291: göç çalışması, mutabakat, veri sahibi kabulü, dondurma sonrası Göç Değişiklik Listesi.
CREATE TABLE goc_calismasi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), tur text NOT NULL CHECK (tur IN ('Deneme', 'Gerçek')), kaynak_ozeti text NOT NULL, sonuc jsonb NOT NULL, mutabik boolean NOT NULL, kabul text CHECK (kabul IN ('Kabul Edildi', 'Reddedildi')), kabul_zamani timestamptz, yapan_ref text REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE goc_degisiklik (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), kaynak text NOT NULL, kayit text NOT NULL, alan text NOT NULL, eski text, yeni text NOT NULL, gerekce text NOT NULL, durum text NOT NULL DEFAULT 'GMY Değerlendirmesinde' CHECK (durum IN ('GMY Değerlendirmesinde', 'Uygun', 'Uygun Değil', 'Uygulandı')), giren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), uygulama_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON goc_calismasi, goc_degisiklik TO yatonet_uygulama;
